/**
 * bpmn-js DI module: host-bridge override for element copy/paste in sandboxed
 * webviews.
 *
 * The default clipboard path is bpmn-js-native-copy-paste's `NativeCopyPaste`,
 * which emits a wire-compatible payload; this module is only
 * registered when the host cannot reach the system clipboard from the webview
 * (e.g. a VS Code iframe lacking `clipboard-read`/`clipboard-write`). It
 * disables `NativeCopyPaste` and routes copy/paste through a {@link ClipboardBridge}
 * the host wires to its extension-host clipboard, keeping the same prefixed-JSON
 * payload so webview-copy ↔ browser-paste stays interoperable.
 *
 * Uses didi DI value injection (`elementClipboardBridge`) rather than `config.*`
 * so the bridge is always available when the module loads.
 */
import { createReviver } from "bpmn-js-native-copy-paste/lib/PasteUtil.js";
import type EventBus from "diagram-js/lib/core/EventBus";
import type Canvas from "diagram-js/lib/core/Canvas";
import type CopyPaste from "diagram-js/lib/features/copy-paste/CopyPaste";

/**
 * Bridge interface for clipboard operations routed through the host (e.g. the
 * VS Code extension host) when the webview cannot reach the system clipboard.
 */
export interface ClipboardBridge {
    // Reads clipboard text from the host.
    requestClipboard: () => Promise<string>;
    // Writes text to the system clipboard via the host. May be async; the return
    // is ignored, so a host may fire-and-forget or await internally.
    writeClipboard: (text: string) => void | Promise<void>;
}

/** Minimal surface of camunda's `nativeCopyPaste` service used here. */
interface NativeCopyPaste {
    toggle(enabled: boolean): void;
}

/** Payload of the `copyPaste.elementsCopied` event; `tree` is serialized as-is. */
interface ElementsCopiedContext {
    tree: unknown;
    hints?: { clip?: boolean };
}

/** Payload of the `copyPaste.pasteElements` event; carries the paste context to fill. */
interface PasteElementsContext {
    tree?: unknown;
    hints?: unknown;
}

const CLIP_PREFIX = "bpmn-js-clip----";

function isTextEditingElement(element: Element | null): boolean {
    return (
        element instanceof HTMLInputElement ||
        element instanceof HTMLTextAreaElement ||
        (element as HTMLElement | null)?.isContentEditable === true
    );
}

/**
 * Intercepts `copyPaste.elementsCopied` and `copyPaste.pasteElements` at
 * priority 2051 (above NativeCopyPaste's 2050) to route element clipboard
 * operations through the host bridge.
 *
 * Disables `NativeCopyPaste` on construction so no `navigator.clipboard` calls
 * are made from the sandboxed webview (where they would be denied).
 *
 * Re-focuses the canvas SVG after keyboard-triggered selection changes
 * (e.g. Cmd+A) to prevent subsequent Cmd+C from silently failing when the
 * properties panel steals focus.
 */
class BridgedClipboard {
    static $inject = [
        "elementClipboardBridge",
        "eventBus",
        "copyPaste",
        "moddle",
        "nativeCopyPaste",
        "canvas",
    ];

    constructor(
        bridge: ClipboardBridge,
        eventBus: EventBus,
        copyPaste: CopyPaste,
        moddle: unknown,
        nativeCopyPaste: NativeCopyPaste,
        canvas: Canvas,
    ) {
        // Disable NativeCopyPaste so the bridge owns copy/paste in this webview.
        nativeCopyPaste.toggle(false);

        const { requestClipboard, writeClipboard } = bridge;

        // Pending serialized BPMN data waiting to be written to the clipboard
        // via the next `copy` event. Set by the copy interceptor, consumed by
        // the capture-phase `copy` event handler.
        let pendingClipData: string | null = null;

        // ── Capture-phase copy event handler ─────────────────────────────
        // VS Code's webview clipboard handler listens for `copy` events and
        // forwards `clipboardData` to the extension host. By hijacking the
        // event in capture phase (before VS Code's handler sees it), we
        // inject our serialized BPMN data synchronously — eliminating the
        // race condition where VS Code's handler would otherwise copy the
        // DOM text selection (e.g. a stale line break after Cmd+A).
        const onDocumentCopy = (e: ClipboardEvent): void => {
            const elementsPayload = pendingClipData;
            pendingClipData = null;
            // diagram-js copies elements only from a keydown on the focused canvas
            // and prevents its default, so hosts that don't re-dispatch a copy
            // leave the payload stale. Focus decides, not e.target: Chromium
            // targets the copy at the DOM selection, which stays in a field
            // after a canvas click.
            if (!elementsPayload || !canvas.isFocused()) {
                return;
            }
            e.preventDefault();
            e.stopImmediatePropagation();
            e.clipboardData?.setData("text/plain", elementsPayload);
        };
        document.addEventListener("copy", onDocumentCopy, true);
        eventBus.on("diagram.destroy", () => {
            document.removeEventListener("copy", onDocumentCopy, true);
        });

        // ── Copy interceptor ─────────────────────────────────────────────
        eventBus.on<ElementsCopiedContext>("copyPaste.elementsCopied", 2051, (context) => {
            const serialized = CLIP_PREFIX + JSON.stringify(context.tree);

            // Store for the synchronous copy-event path.
            pendingClipData = serialized;

            /**
             * Also write via the async extension host postMessage path as a
             * backup (handles cases where no copy event fires).
             */
            writeClipboard(serialized);

            context.hints = context.hints || {};
            context.hints.clip = false;
        });

        // ── Paste interceptor ────────────────────────────────────────────
        eventBus.on<PasteElementsContext>("copyPaste.pasteElements", 2051, (context) => {
            if (context.tree) {
                return;
            }

            // Snapshot context NOW, before `return false` sets `defaultPrevented`
            // on the same object.
            const contextSnapshot = { ...context };

            requestClipboard().then((text) => {
                if (!text || !text.startsWith(CLIP_PREFIX)) {
                    return;
                }

                try {
                    const json = text.substring(CLIP_PREFIX.length);
                    const tree = JSON.parse(json, createReviver(moddle));
                    copyPaste.paste({ ...contextSnapshot, tree });
                } catch (error) {
                    console.error("Failed to deserialise clipboard content", error);
                }
            });

            return false;
        });

        // ── Focus fix ────────────────────────────────────────────────────
        // Re-focus the canvas SVG after selection changes. diagram-js
        // Keyboard binds to the SVG and Canvas.focus() is only called on
        // element.mousedown. After keyboard-triggered selection changes
        // (e.g. Cmd+A), the properties panel re-render can steal focus,
        // causing subsequent Cmd+C to silently fail.
        //
        // This focus repair is bridge-path-only by design: it was never active
        // on the native path (the module is not registered there), and it fixes
        // side-by-side webview focus theft that only arises in a host shell.
        //
        // The `hasFocus()` guard prevents cross-pane focus theft: every
        // external XML edit (e.g. typing in a side-by-side text editor)
        // re-imports the diagram, and importXML fires `selection.changed`
        // unconditionally. Without the guard, canvas.focus() would yank the
        // caret out of that separate editor pane on every keystroke. A
        // webview iframe's document.hasFocus() is false while another VS Code
        // pane is focused, so this runs only when the webview truly has focus.
        eventBus.on("selection.changed", () => {
            requestAnimationFrame(() => {
                if (!document.hasFocus()) {
                    return;
                }
                if (isTextEditingElement(document.activeElement)) {
                    return;
                }
                canvas.focus();
            });
        });
    }
}

export const BridgedClipboardModule = {
    __init__: ["bridgedClipboard"],
    bridgedClipboard: ["type", BridgedClipboard],
};
