/**
 * bpmn-js DI service that decorates the diagram-js `popupMenu` to intercept
 * the `bpmn-append` and `bpmn-create` menus from the
 * `bpmn-js-create-append-anything` plugin.
 *
 * Instead of the default flat dropdown, this service renders a custom
 * Preact-based two-panel overlay with element templates on the left and
 * categorised BPMN elements on the right.
 */
import { render, h } from "preact";
import { AppendMenuOverlay } from "./components/AppendMenuOverlay";
import { classifyEntries, executeEntryAction } from "./types";
import { executeTemplateTypeAction } from "./templateTypeAction";
import { getPopupMenuContext } from "./upstreamInternals/popupMenuInternals";
import type { PopupMenuEntryAction, Translate } from "./types";
import type { ElementTemplate } from "@miragon/bpmn-modeler-element-template-chooser";
import { fallbackTranslate } from "@miragon/bpmn-modeler-element-template-chooser/types";

interface MenuPosition {
    x: number;
    y: number;
}

// Only the members the override reads or reassigns on the diagram-js popupMenu.
interface PopupMenuLike {
    open: (target: unknown, providerId: string, position: MenuPosition, options?: unknown) => void;
    close: () => void;
    isOpen: () => boolean;
}

interface CanvasLike {
    getContainer(): HTMLElement;
    focus(): void;
}

interface EventBusLike {
    on(events: string | string[], cb: () => void): void;
}

interface InjectorLike {
    get<T = unknown>(name: string, strict: false): T | null;
}

interface ElementTemplatesLike {
    getLatest(): ElementTemplate[];
    createElement(template: ElementTemplate, options?: { presetId?: string }): unknown;
}

// Provider IDs that this override intercepts.
const INTERCEPTED_PROVIDERS = new Set(["bpmn-append", "bpmn-create"]);

// Maximum number of favourite BPMN elements.
const MAX_FAVOURITES = 6;

/**
 * Decorates `popupMenu.open()` so that `bpmn-append` and `bpmn-create`
 * menus render in a custom overlay rather than the default popup.
 *
 * All other popup menu types (e.g. `bpmn-replace`) pass through to the
 * original implementation unchanged.
 */
class AppendMenuOverride {
    static $inject = ["popupMenu", "canvas", "eventBus", "injector"];

    private favourites: string[] = [];

    /**
     * Sets the favourite BPMN element types to pin at the top of the palette.
     * Maximum of 6 items; extras are silently dropped.
     */
    setFavourites(types: string[]): void {
        this.favourites = types.slice(0, MAX_FAVOURITES);
    }

    constructor(
        popupMenu: PopupMenuLike,
        canvas: CanvasLike,
        eventBus: EventBusLike,
        injector: InjectorLike,
    ) {
        const elementTemplates = injector.get<ElementTemplatesLike>("elementTemplates", false);
        const translate = injector.get<Translate>("translate", false) ?? fallbackTranslate;

        const originalOpen = popupMenu.open.bind(popupMenu);
        const originalClose = popupMenu.close.bind(popupMenu);
        const originalIsOpen = popupMenu.isOpen.bind(popupMenu);

        let customMenuOpen = false;
        let closeCustomMenu: (() => void) | null = null;

        // Tears down the custom overlay and resets state.
        const destroyCustomMenu = () => {
            if (closeCustomMenu) {
                closeCustomMenu();
                closeCustomMenu = null;
            }
            customMenuOpen = false;
        };

        // --- Override popupMenu.open ---
        popupMenu.open = (
            target: unknown,
            providerId: string,
            position: MenuPosition,
            options?: unknown,
        ) => {
            if (!INTERCEPTED_PROVIDERS.has(providerId)) {
                return originalOpen(target, providerId, position, options);
            }

            /**
             * Close any currently open menu (custom or default).
             */
            if (customMenuOpen) {
                destroyCustomMenu();
            } else if (originalIsOpen()) {
                originalClose();
            }

            // Collect entries from all registered providers.
            const context = getPopupMenuContext(popupMenu, target, providerId);

            // The upstream providers build their entries from `getLatest()` (latest
            // engine-compatible version per id); enriching from any other set could
            // pair an entry with another version and resolve the wrong step preset.
            let allTemplates: ElementTemplate[] = [];
            if (elementTemplates) {
                try {
                    allTemplates = elementTemplates.getLatest();
                } catch {
                    // elementTemplates service may not have templates loaded yet.
                }
            }

            const classified = classifyEntries(context.entries, allTemplates);

            const canvasContainer: HTMLElement = canvas.getContainer();

            // Append the overlay to document.body so it renders above
            // the properties panel (which is a sibling of the canvas).
            const container = document.createElement("div");
            container.className = "am-overlay-root";
            // The overlay leaves the instance's themed subtree, so copy the
            // instance's `data-bpmn-theme` onto its own root — otherwise a dark
            // instance would show a light append menu.
            const themeKind = canvasContainer
                .closest("[data-bpmn-theme]")
                ?.getAttribute("data-bpmn-theme");
            if (themeKind) {
                container.setAttribute("data-bpmn-theme", themeKind);
            }
            document.body.appendChild(container);

            const close = () => {
                render(null, container);
                container.remove();
            };

            // Close the overlay, run the chosen action, then return focus to the
            // canvas so keyboard-driven modelling chains without the mouse
            // (A → nav → Enter → A → …); on unmount focus would otherwise fall to
            // <body>. Deferred a microtask and gated on directEditing so we never
            // steal the caret from a label-edit session that creating may open.
            const finishSelection = (run: () => void) => {
                close();
                customMenuOpen = false;
                closeCustomMenu = null;
                run();
                queueMicrotask(() => {
                    const directEditing = injector.get<{ isActive?: () => boolean }>(
                        "directEditing",
                        false,
                    );
                    if (directEditing?.isActive?.()) {
                        return;
                    }
                    canvas.focus();
                });
            };

            const handleSelect = (action: PopupMenuEntryAction | undefined, event: Event) => {
                finishSelection(() => executeEntryAction(action, event));
            };

            const handleTemplateTypeSelect = (
                template: ElementTemplate,
                bpmnType: string,
                event: Event,
                presetId: string | undefined,
            ) => {
                const create = injector.get<{
                    start(event: Event, element: unknown, context?: { source?: unknown }): void;
                }>("create", false);
                if (!elementTemplates || !create) {
                    return;
                }
                finishSelection(() =>
                    executeTemplateTypeAction(
                        {
                            elementTemplates,
                            autoPlace:
                                injector.get<{ append(source: unknown, element: unknown): void }>(
                                    "autoPlace",
                                    false,
                                ) || undefined,
                            create,
                            mouse:
                                injector.get<{ getLastMoveEvent(): Event }>("mouse", false) ||
                                undefined,
                        },
                        { providerId: providerId as "bpmn-append" | "bpmn-create", target },
                        template,
                        bpmnType,
                        event,
                        presetId,
                    ),
                );
            };

            const handleCancel = () => {
                close();
                customMenuOpen = false;
                closeCustomMenu = null;
                canvas.focus();
            };

            const canvasBounds = canvasContainer.getBoundingClientRect();

            render(
                h(AppendMenuOverlay, {
                    templateEntries: classified.templates,
                    bpmnGroups: classified.bpmnGroups,
                    favourites: this.favourites,
                    translate,
                    position: { x: position.x, y: position.y },
                    canvasBounds: {
                        left: canvasBounds.left,
                        top: canvasBounds.top,
                        right: canvasBounds.right,
                        bottom: canvasBounds.bottom,
                    },
                    onSelect: handleSelect,
                    onTemplateTypeSelect: handleTemplateTypeSelect,
                    onCancel: handleCancel,
                }),
                container,
            );

            customMenuOpen = true;
            closeCustomMenu = close;
        };

        // --- Override popupMenu.isOpen ---
        popupMenu.isOpen = () => {
            return customMenuOpen || originalIsOpen();
        };

        // --- Override popupMenu.close ---
        popupMenu.close = () => {
            if (customMenuOpen) {
                destroyCustomMenu();
            }
            originalClose();
        };

        // --- Auto-close on diagram events ---
        eventBus.on(["contextPad.close", "canvas.viewbox.changing", "commandStack.changed"], () => {
            if (customMenuOpen) {
                destroyCustomMenu();
            }
        });
    }
}

export { AppendMenuOverride };
